import requests, re, time, json, datetime, csv, os, sys
from collections import Counter
import matplotlib.pyplot as plt

HEADERS = {"User-Agent": "Mozilla/5.0 (compatible; compliance-audit/1.0)"}
DELAY = 0.6

# Rate limit tracking
req_count = 0
last_req_time = 0

def get(url):
    global req_count, last_req_time
    # Ensure delay between requests
    now = time.time()
    wait = last_req_time + DELAY - now
    if wait > 0:
        time.sleep(wait)
    try:
        r = requests.get(url, headers=HEADERS, timeout=30)
        last_req_time = time.time()
        req_count += 1
        if r.status_code == 200:
            return r.text
        if r.status_code == 404:
            return None
        # For other errors, return None but still record
        return None
    except Exception as e:
        print(f"Error fetching {url}: {e}")
        last_req_time = time.time()
        req_count += 1
        return None

def get_branch(html):
    m = re.search(r'defaultBranch":"([^"]+)"', html)
    if m:
        return m.group(1)
    return None

def get_primary_language(html):
    m = re.search(r'primaryLanguage":\{"name":"([^"]+)"\}', html)
    if m:
        return m.group(1)
    # fallback: look for language search link after Languages heading
    m = re.search(r'<h2[^>]*>Languages</h2>.*?<a[^>]*href="/canada-ca/[^/]+/search\?l=([^"]+)"', html, re.DOTALL)
    if m:
        return m.group(1).capitalize()
    return None

def get_open_issues_count(html):
    # Look for issues count in the issues tab on repo page
    # Some repos have "Issues <span>count</span>"
    m = re.search(r'<a[^>]*href="/canada-ca/[^/]+/issues"[^>]*>.*?<span[^>]*>(\d+)</span>\s*Issues', html, re.DOTALL)
    if m:
        return int(m.group(1))
    # Another pattern: <span id="issues_count"> or similar
    m = re.search(r'<span[^>]*class="Counter[^"]*"[^>]*>(\d+)</span>\s*Issues', html, re.DOTALL)
    if m:
        return int(m.group(1))
    # Try more generic: text containing Issues and digits
    m = re.search(r'<a[^>]*href="/canada-ca/[^/]+/issues\?q=[^"]*"[^>]*>[^<]*<span[^>]*>\s*(\d+)\s*</span>\s*Issues', html, re.DOTALL)
    if m:
        return int(m.group(1))
    return None

def get_last_commit_date(repo, branch):
    atom = get(f"https://github.com/canada-ca/{repo}/commits/{branch}.atom")
    if atom:
        m = re.search(r'<updated>([^<]+)</updated>', atom)
        if m:
            return m.group(1)
    return None

def raw_file(repo, branch, path):
    return get(f"https://raw.githubusercontent.com/canada-ca/{repo}/{branch}/{path}")

OPEN_LICENCES = {
    "MIT": "MIT", "Apache": "Apache-2.0", "GPL": "GPL-3.0", "LGPL": "LGPL-3.0",
    "BSD": "BSD-3-Clause", "ISC": "ISC", "CC0": "CC0-1.0", "OGL": "OGL-Canada",
    "Unlicense": "Unlicense", "MPL": "MPL-2.0", "EPL": "EPL-2.0", "AGPL": "AGPL-3.0",
    "Artistic": "Artistic-2.0", "CDDL": "CDDL-1.0", "CPL": "CPL-1.0", "WTFPL": "WTFPL",
    "Zlib": "Zlib", "BSL": "BSL-1.0", "PSF": "PSF-2.0", "Python": "PSF-2.0",
}

def detect_licence(text):
    if not text:
        return None
    upper = text.upper()
    for key, spdx in OPEN_LICENCES.items():
        if key.upper() in upper:
            return spdx
    if "CROWN COPYRIGHT" in upper and "LICENCE" in upper:
        return "Crown Copyright"
    if "PERMISSION IS HEREBY GRANTED" in upper:
        return "MIT"
    return None

def has_bilingual_content(text):
    if not text:
        return False
    # Simple heuristic: look for common French words/phrases and English
    lower = text.lower()
    french_indicators = ["français", "française", "gouvernement", "canada", "français", "utilisation",
                         "contribution", "sécurité", "licence", "développement", "projet",
                         "français", "comment contribuer", "commentaires", "aide", "problèmes",
                         "code source", "logiciel", "données", "bienvenue", "merci", "prérequis"]
    english_indicators = ["english", "welcome", "government", "canada", "usage", "contribution",
                          "security", "license", "development", "project", "how to",
                          "feedback", "help", "issues", "source code", "software", "data"]
    fr_count = sum(1 for w in french_indicators if w in lower)
    en_count = sum(1 for w in english_indicators if w in lower)
    return fr_count >= 2 and en_count >= 2

def readme_clarity(text):
    if not text:
        return "Unknown"
    # Check if it explains what, who, how
    checks = 0
    lower = text.lower()
    if any(k in lower for k in ["what is", "about", "overview", "description", "purpose"]):
        checks += 1
    if any(k in lower for k in ["who", "for", "audience", "target", "users", "intended"]):
        checks += 1
    if any(k in lower for k in ["how to use", "usage", "getting started", "install", "run", "quick start", "guide"]):
        checks += 1
    if checks >= 3:
        return "Good"
    elif checks >= 1:
        return "Fair"
    else:
        return "Poor"

def security_policy_status(security_text):
    if not security_text:
        return "Missing"
    lower = security_text.lower()
    if any(k in lower for k in ["report", "vulnerability", "disclosure", "security", "contact", "email", "submit"]):
        return "Present"
    return "Incomplete"

def has_ci_workflows(repo, branch):
    # Check if .github/workflows directory exists
    html = get(f"https://github.com/canada-ca/{repo}/tree/{branch}/.github/workflows")
    if html and ("yml" in html or "yaml" in html or ".github" in html):
        return True
    # Also check .github/workflows might be empty or 404
    return False

def has_actions_runs(repo):
    html = get(f"https://github.com/canada-ca/{repo}/actions")
    if not html:
        return None
    if "No runs" in html or "There are no workflow runs" in html or "This workflow has no runs" in html:
        return False
    if "workflow run" in html.lower() or "runs" in html.lower():
        return True
    return False

def check_workflow_for_security(repo, branch):
    # Try to list workflow files
    html = get(f"https://github.com/canada-ca/{repo}/tree/{branch}/.github/workflows")
    if not html:
        return False
    # Extract file names
    files = re.findall(r'href="/canada-ca/[^/]+/blob/[^/]+/\.github/workflows/([^"]+\.ya?ml)"', html)
    if not files:
        return False
    for f in files:
        text = raw_file(repo, branch, f".github/workflows/{f}")
        if text and any(k in text.lower() for k in ["codeql", "npm audit", "pip-audit", "snyk", "trivy", "bandit", "security", "scan", "clair", "grype"]):
            return True
    return False

def check_workflow_for_tests(repo, branch):
    html = get(f"https://github.com/canada-ca/{repo}/tree/{branch}/.github/workflows")
    if not html:
        return False
    files = re.findall(r'href="/canada-ca/[^/]+/blob/[^/]+/\.github/workflows/([^"]+\.ya?ml)"', html)
    if not files:
        return False
    for f in files:
        text = raw_file(repo, branch, f".github/workflows/{f}")
        if text and any(k in text.lower() for k in ["pytest", "jest", "npm test", "go test", "rspec", "mocha", "cypress", "test", "unit test", "integration test"]):
            return True
    return False

def dependency_update_policy(repo, branch):
    # Check for dependabot.yml
    dep = raw_file(repo, branch, ".github/dependabot.yml")
    if not dep:
        dep = raw_file(repo, branch, ".github/dependabot.yaml")
    if dep:
        return "Automated"
    # Check for renovate.json
    ren = raw_file(repo, branch, "renovate.json")
    if not ren:
        ren = raw_file(repo, branch, ".renovaterc")
    if ren:
        return "Automated"
    return "Manual"

def issue_response_quality(repo, branch, open_issues_count):
    if open_issues_count is not None and open_issues_count == 0:
        return "No Issues"
    # Fetch issues page sorted by recently updated
    html = get(f"https://github.com/canada-ca/{repo}/issues?q=is%3Aissue+is%3Aopen+sort%3Aupdated-desc")
    if not html:
        return "Unknown"
    # Extract issue links and comment counts
    # Look for 5 most recent open issues
    issues = re.findall(r'href="(/canada-ca/[^/]+/issues/\d+)"', html)
    seen = []
    for issue in issues:
        if issue not in seen:
            seen.append(issue)
        if len(seen) >= 5:
            break
    if not seen:
        return "No Issues" if (open_issues_count is not None and open_issues_count == 0) else "Unknown"
    cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=180)
    for issue_url in seen[:5]:
        issue_html = get(f"https://github.com{issue_url}")
        if not issue_html:
            continue
        # Extract comment authors and dates
        # Find all comment relative-time datetimes
        datetimes = re.findall(r'<relative-time datetime="([^"]+)"', issue_html)
        # Find all comment authors (usernames)
        authors = re.findall(r'<a[^>]*class="author Link--primary[^"]*"[^>]*>([^<]+)</a>', issue_html)
        # The original reporter is usually the author of the first comment (issue body)
        if not authors:
            continue
        reporter = authors[0].strip()
        # Check if any other author commented in last 6 months
        for i, dt_str in enumerate(datetimes):
            try:
                dt = datetime.datetime.fromisoformat(dt_str.replace("Z", "+00:00"))
                if dt > cutoff and i < len(authors) and authors[i].strip() != reporter:
                    return "Active"
            except Exception:
                continue
    return "Stale"

def release_notes_quality(repo):
    html = get(f"https://github.com/canada-ca/{repo}/releases")
    if not html:
        return "Unknown"
    if "There are no releases" in html or "No releases published" in html:
        return "No Releases"
    # Check first release
    # Look for release description
    m = re.search(r'<div[^>]*class="release-entry"[^>]*>.*?</div>.*?</div>', html, re.DOTALL)
    if m:
        entry = m.group(0)
        # If description contains more than just version/tag, it's detailed
        if len(entry) > 500 and ("change" in entry.lower() or "fix" in entry.lower() or "add" in entry.lower() or "update" in entry.lower() or "feature" in entry.lower()):
            return "Detailed"
    # If releases exist but are minimal
    return "Version-only"

# Load repos
with open("/tmp/repos_raw.txt") as f:
    REPOS = [line.strip() for line in f if line.strip()]

print(f"Total repos to audit: {len(REPOS)}")

results = []
checkpoint_file = "/tmp/checkpoint.json"

for idx, repo in enumerate(REPOS):
    print(f"\n[{idx+1}/{len(REPOS)}] Auditing {repo}...")
    res = {"repo_name": repo, "repo_url": f"https://github.com/canada-ca/{repo}"}

    # Main page
    html = get(f"https://github.com/canada-ca/{repo}")
    if not html:
        print(f"  Could not access repo page. Recording Unknown.")
        for col in ["primary_language", "readme_exists", "bilingual", "readme_clarity", "licence", "security_policy",
                    "contributing_guide", "has_security_scanning_in_ci", "has_tests_in_ci", "dependency_update_policy",
                    "issue_response_quality", "release_notes_quality", "last_commit_date", "days_since_last_commit",
                    "maintained", "open_issues_count", "standards_met", "compliance_status", "gaps"]:
            res[col] = "Unknown"
        results.append(res)
        continue

    branch = get_branch(html)
    if not branch:
        branch = "master"  # fallback
    res["primary_language"] = get_primary_language(html) or "Unknown"
    open_issues_count = get_open_issues_count(html)
    res["open_issues_count"] = open_issues_count if open_issues_count is not None else "Unknown"

    # README
    readme = raw_file(repo, branch, "README.md")
    if not readme:
        readme = raw_file(repo, branch, "readme.md")
    if not readme:
        readme = raw_file(repo, branch, "README.adoc")
    res["readme_exists"] = "Yes" if readme else "No"
    res["bilingual"] = "Yes" if (readme and has_bilingual_content(readme)) else "No" if readme else "Unknown"
    res["readme_clarity"] = readme_clarity(readme) if readme else "Unknown"

    # Licence
    licence_text = raw_file(repo, branch, "LICENSE") or raw_file(repo, branch, "LICENSE.txt") or raw_file(repo, branch, "LICENSE.md") or raw_file(repo, branch, "LICENCE") or raw_file(repo, branch, "LICENCE.md")
    res["licence"] = detect_licence(licence_text) or "Unknown"

    # Security policy
    sec = raw_file(repo, branch, "SECURITY.md") or raw_file(repo, branch, ".github/SECURITY.md") or raw_file(repo, branch, "docs/SECURITY.md")
    res["security_policy"] = security_policy_status(sec)

    # Contributing guide
    contrib = raw_file(repo, branch, "CONTRIBUTING.md") or raw_file(repo, branch, "CONTRIBUTING.adoc")
    res["contributing_guide"] = "Yes" if contrib else "No"

    # CI
    has_workflows = has_ci_workflows(repo, branch)
    has_runs = has_actions_runs(repo)
    if not has_workflows:
        res["has_security_scanning_in_ci"] = "No CI"
        res["has_tests_in_ci"] = "No CI"
    elif has_runs is False:
        res["has_security_scanning_in_ci"] = "No CI"
        res["has_tests_in_ci"] = "No CI"
    elif has_runs is True:
        sec_scan = check_workflow_for_security(repo, branch)
        res["has_security_scanning_in_ci"] = "Yes" if sec_scan else "No"
        test_scan = check_workflow_for_tests(repo, branch)
        res["has_tests_in_ci"] = "Yes" if test_scan else "No"
    else:
        res["has_security_scanning_in_ci"] = "Unknown"
        res["has_tests_in_ci"] = "Unknown"

    # Dependency update policy
    res["dependency_update_policy"] = dependency_update_policy(repo, branch)

    # Issue response quality
    oic = open_issues_count if isinstance(open_issues_count, int) else 0
    res["issue_response_quality"] = issue_response_quality(repo, branch, oic)

    # Release notes quality
    res["release_notes_quality"] = release_notes_quality(repo)

    # Last commit date
    last_commit = get_last_commit_date(repo, branch)
    if last_commit:
        try:
            dt = datetime.datetime.fromisoformat(last_commit.replace("Z", "+00:00"))
            res["last_commit_date"] = dt.strftime("%Y-%m-%d")
            days = (datetime.datetime.now(datetime.timezone.utc) - dt).days
            res["days_since_last_commit"] = days
            res["maintained"] = "Yes" if days <= 365 else "No"
        except Exception as e:
            res["last_commit_date"] = "Unknown"
            res["days_since_last_commit"] = "Unknown"
            res["maintained"] = "Unknown"
    else:
        res["last_commit_date"] = "Unknown"
        res["days_since_last_commit"] = "Unknown"
        res["maintained"] = "Unknown"

    # Standards met
    standards = [
        ("Bilingual README", res["bilingual"] == "Yes"),
        ("Open licence", res["licence"] != "Unknown"),
        ("Security policy", res["security_policy"] == "Present"),
        ("Contributing guide", res["contributing_guide"] == "Yes"),
        ("Actively maintained", res["maintained"] == "Yes")
    ]
    gaps = [s[0] for s in standards if not s[1]]
    standards_met = sum(1 for s in standards if s[1])
    res["standards_met"] = standards_met
    if standards_met == 5:
        res["compliance_status"] = "Full"
    elif standards_met >= 2:
        res["compliance_status"] = "Partial"
    else:
        res["compliance_status"] = "Non-compliant"
    res["gaps"] = ", ".join(gaps) if gaps else "None"

    results.append(res)
    print(f"  Standards met: {standards_met}, compliance: {res['compliance_status']}, gaps: {res['gaps']}")
    # Save checkpoint every 5 repos
    if (idx + 1) % 5 == 0:
        with open(checkpoint_file, "w") as f:
            json.dump(results, f, indent=2)
        print(f"  Checkpoint saved. Requests so far: {req_count}")

# Final save
with open(checkpoint_file, "w") as f:
    json.dump(results, f, indent=2)

print(f"\nAudit complete. Total requests: {req_count}")
print(f"Results saved to {checkpoint_file}")

# Write CSV
columns = [
    "repo_name", "repo_url", "primary_language", "readme_exists", "bilingual", "readme_clarity",
    "licence", "security_policy", "contributing_guide", "has_security_scanning_in_ci",
    "has_tests_in_ci", "dependency_update_policy", "issue_response_quality", "release_notes_quality",
    "last_commit_date", "days_since_last_commit", "maintained", "open_issues_count", "standards_met",
    "compliance_status", "gaps"
]

with open("/logs/agent/compliance_matrix.csv", "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=columns)
    writer.writeheader()
    for r in results:
        writer.writerow(r)

print("CSV written to /logs/agent/compliance_matrix.csv")

import requests, re, json, time

def get(url):
    time.sleep(0.5)
    try:
        r = requests.get(url, headers={"User-Agent":"Mozilla/5.0"}, timeout=30)
        return r.text if r.status_code == 200 else None
    except Exception as e:
        return None

html = get("https://github.com/canada-ca/ore-ero")
if html:
    # Look for open issues count in embedded JSON
    m = re.search(r'openIssuesCount\":(\d+)', html)
    print("openIssuesCount:", m.group(1) if m else "None")
    m2 = re.search(r'\"issues\":\{\"totalCount\":(\d+)', html)
    print("issues totalCount:", m2.group(1) if m2 else "None")
    m3 = re.search(r'\"openIssues\":\{\"totalCount\":(\d+)', html)
    print("openIssues totalCount:", m3.group(1) if m3 else "None")
    m4 = re.search(r'open_issues_count\":(\d+)', html)
    print("open_issues_count:", m4.group(1) if m4 else "None")
    # Look for any number near "Issues" in the page title
    m5 = re.search(r'<title>[^<]*Issues[^<]*(\d+)', html, re.IGNORECASE)
    print("title issues:", m5.group(1) if m5 else "None")
    # Look for JSON with issue counts
    scripts = re.findall(r'<script type="application/json"[^>]*>(.*?)</script>', html, re.DOTALL)
    for i, s in enumerate(scripts):
        if 'issue' in s.lower() or 'count' in s.lower():
            try:
                data = json.loads(s)
                # Search recursively for issue counts
                def find_issues(obj, path=""):
                    if isinstance(obj, dict):
                        for k, v in obj.items():
                            if isinstance(v, int) and 'issue' in k.lower() and v > 0:
                                print(f"Script {i} {path}.{k}: {v}")
                            elif isinstance(v, (dict, list)):
                                find_issues(v, f"{path}.{k}")
                    elif isinstance(obj, list):
                        for idx, item in enumerate(obj):
                            find_issues(item, f"{path}[{idx}]")
                find_issues(data)
            except Exception as e:
                pass

# Also test issues page
html2 = get("https://github.com/canada-ca/ore-ero/issues?q=is%3Aissue+is%3Aopen")
if html2:
    m = re.search(r'<title>[^<]*(\d+)\s+Open\s+issue', html2, re.IGNORECASE)
    print("issues page title:", m.group(1) if m else "None")
    # Look for data in the page
    m2 = re.search(r'\"issueCount\":(\d+)', html2)
    print("issueCount:", m2.group(1) if m2 else "None")
    m3 = re.search(r'\"totalCount\":(\d+)', html2)
    print("totalCount:", m3.group(1) if m3 else "None")
